class Spieler {
  constructor(name, punkte) {
    this.name = name;
    this.punkte = punkte;
  }
}

let spieler = [
  new Spieler('Mia', 45),
  new Spieler('Jonas', 82),
  new Spieler('Zoe', 30),
];

